-- exec-once equivalent. `hl.on("hyprland.start")` only fires on the
-- compositor's first frame, so anything loaded later (a reload, or a
-- config written after the session began) never starts. Running at parse
-- time always works; the pgrep guard keeps reloads from starting seconds.
-- global (not local): the split modules call it too
function autostart(guard, cmd, exact)
    -- Prefer `pgrep -x <name>`: matching whole command lines (-f) also
    -- matches any unrelated process that merely MENTIONS the command,
    -- and then the program never starts. Where -f is unavoidable (shell
    -- pipelines), [b]racket the first char so the check can't match the
    -- `sh -c` running it.
    local check
    if exact then
        check = "pgrep -x " .. guard
    else
        check = "pgrep -f \"[" .. guard:sub(1, 1) .. "]" .. guard:sub(2) .. "\""
    end
    hl.exec_cmd(check .. " >/dev/null 2>&1 || { " .. cmd .. " ; } &")
end


